package main
import("errors";"fmt")
type RegistryHeadAbsentError struct{}
func(RegistryHeadAbsentError)Error()string{return "read transition registry: head is absent"}
func main(){hasHead:=false;rerr:=fmt.Errorf("wrapped: %w",RegistryHeadAbsentError{});var target RegistryHeadAbsentError;fmt.Println(!hasHead && errors.As(rerr, &target));rerr=errors.New("genuine failure");fmt.Println(!hasHead && errors.As(rerr, &target))}
